207	impl ListMeasuringBehavior {
208	    fn reset(&mut self) {
209	        match self {
210	            ListMeasuringBehavior::Measure(has_measured) => *has_measured = false,
211	            ListMeasuringBehavior::Visible => {}
212	        }
213	    }
214	}
