                rendered_height += element_size.height;
                measured_items.push_front(ListItem::Measured {
                    size: element_size,
                    focus_handle,
                });
                item_layouts.push_front(ItemLayout {
                    index: item_index,
                    element,
                    size: element_size,
                });
